#!/usr/bin/env bash
# AI: below section was generated by an AI
set -euo pipefail

if ! git diff --quiet || ! git diff --cached --quiet; then
  echo "Refusing to update a working tree with uncommitted changes." >&2
  exit 1
fi

if git remote get-url upstream >/dev/null 2>&1; then
  git remote set-url upstream https://github.com/wled/WLED.git
else
  git remote add upstream https://github.com/wled/WLED.git
fi

git fetch upstream --tags --prune

latest_tag="$(
  git tag --list 'v*' --sort=-v:refname |
    awk '/^v[0-9]+\.[0-9]+\.[0-9]+$/ { print; exit }'
)"

if [[ -z "$latest_tag" ]]; then
  echo "No stable WLED release tag was found." >&2
  exit 1
fi

if git merge-base --is-ancestor "$latest_tag" HEAD; then
  echo "Already current with ${latest_tag}."
  if [[ -n "${GITHUB_OUTPUT:-}" ]]; then
    echo "changed=false" >> "$GITHUB_OUTPUT"
    echo "release=${latest_tag}" >> "$GITHUB_OUTPUT"
  fi
  exit 0
fi

if ! git merge --no-edit --no-ff "$latest_tag"; then
  git merge --abort
  echo "WLED ${latest_tag} conflicts with Loomx changes; no update was applied." >&2
  exit 20
fi

echo "Merged stable WLED release ${latest_tag}."
if [[ -n "${GITHUB_OUTPUT:-}" ]]; then
  echo "changed=true" >> "$GITHUB_OUTPUT"
  echo "release=${latest_tag}" >> "$GITHUB_OUTPUT"
fi
# AI: end
